Throughout this paper,
\begin{framed}
  $$\mathcal H\text{ is a real Hilbert space with inner product }\langle\cdot,\cdot\rangle$$
\end{framed}
\noindent and induced norm $\|\cdot\|$. We use $\wto$ to denote weak convergence. \vspace{1em}

We consider the $N$-set convex feasibility problem:
\begin{framed}
 \begin{equation}
  \text{Find~}~x\in \bigcap_{i=1}^N C_i\neq\emptyset~\text{ where }C_i\subseteq\mathcal H\text{ are closed and convex}. \label{eq:cfp}
 \end{equation}
\end{framed}

Given a set $S\subseteq\mathcal H$ and point $x\in\mathcal H$, the \emph{best approximation} to $x$ from $S$ is a point $p\in S$ such that
 $$\|p-x\|=d(x,S):=\inf_{s\in S}\|x-s\|.$$
If for every $x\in\mathcal H$ there exists such a $p$, then $S$ is said to be \emph{proximal}. Additionally, if $p$ is always unique then $S$ is said to be \emph{Chebyshev}. In the latter case, the \emph{projection} onto $S$ is the operator $P_S:\mathcal H\to S$ which maps $x$ to its unique nearest point in $S$ and we write $P_S(x)=p$. The \emph{reflection} about $S$ is the operator $R_S:\mathcal H\to\mathcal H$ defined by $R_S:=2P_S-I$ where $I$ denotes the \emph{identity} operator which maps any $x\in\mathcal H$ to itself.


\begin{fact} \label{fact:projections}
 Let $C\subseteq\mathcal H$ be non-empty closed and convex. Then:
  \begin{enumerate}[(i)]
   \item $C$ is Chebyshev.
   \item (Characterization of projections)
  $$P_C(x)=p \iff \langle x-p,c-p\rangle\leq 0 \text{ for all }c\in C.$$
   \item (Characterization of reflections)
  $$R_C(x)=r \iff \langle x-r,c-r\rangle\leq\frac{1}{2}\|x-r\|^2 \text{ for all }c\in C.$$
   \item (Translation formula) For $y\in\mathcal H$, $P_{y+C}(x)=y+P_C(x-y)$.
   \item (Dilation formula) For $0\neq\lambda\in\mathbb R$, $P_{\lambda C}(x)=\lambda P_C(x/\lambda)$.
   \item If $C$ is a subspace then $P_C$ is linear.
   \item If $C$ is an affine subspace then $P_C$ is affine.
  \end{enumerate}
\end{fact}


Given $A,B\subseteq\mathcal H$  we define the \emph{$2$-set Douglas--Rachford} operator $T_{A,B}:\mathcal H\to\mathcal H$ by
\begin{equation}\label{tab}
 T_{A,B}:=\frac{I+R_BR_A}{2}.
\end{equation}
Note that $ T_{A,B}$ and  $T_{B,A}$ are typically distinct, while for an affine set $A$ we have $T_{A,A}=I$.


Let $T:\mathcal H\to\mathcal H$. We recall that $T$ is \emph{asymptotically regular} if $T^{n}x-T^{n+1}x\to 0$, in norm, for all $x\in\mathcal H$.  We denote the set of \emph{fixed points} of $T$ by $\Fix T=\{x:Tx=x\}$. Let $D\subseteq\mathcal H$ and $T:D\to\mathcal H$. We say $T$ is \emph{nonexpansive} if
   $$\|Tx-Ty\|\leq\|x-y\|\text{ for all }x,y\in D$$
(i.e. $1$-Lipschitz). We say $T$ is \emph{firmly nonexpansive} if
   $$\|Tx-Ty\|^2+\|(I-T)x-(I-T)y\|^2\leq\|x-y\|^2\text{ for all }x,y\in D.$$
It immediately follows that every firmly nonexpansive mapping is nonexpansive.


\begin{fact} \label{fact:nonexpansive}
 Let $A,B\subseteq\mathcal H$ be closed and convex. Then $P_A$ is firmly nonexpansive, $R_A$ is nonexpansive and $T_{A,B}$ is firmly nonexpansive.
\end{fact}


The class of nonexpansive mappings is closed under convex combinations, compositions, etc. The class of firmly nonexpansive mappings is, however,  not so well behaved. For example, even  the composition of two projections onto subspaces need not be firmly nonexpansive (see \cite[Example~4.2.5]{bauschke1997method}).


\begin{lemma}\label{lem:asymregular}
 Let $T_i:\mathcal H\to\mathcal H$ be firmly nonexpansive, for each $i$, and define $T:=T_r\dots T_2\,T_1$. If $\Fix T\neq\emptyset$ then $T$ is asymptotically regular.
\end{lemma}


\begin{lemma} \label{lem:fixedpoints}
 Let $T_i:\mathcal H\to\mathcal H$ be firmly nonexpansive, for each $i$, and define $T:=T_r\dots T_2\,T_1$. If $\bigcap_{i=1}^r\Fix T_i\neq\emptyset$ then $\Fix T=\bigcap_{i=1}^r\Fix T_i$.
\end{lemma}


\begin{theorem}[Opial] \label{thm:opial}
 Let $T:\mathcal H\to\mathcal H$ be nonexpansive, asymptotically regular, and $\Fix T\neq\emptyset$. Then for any $x_0\in\mathcal H$, $T^nx_0$  converges weakly to an element of $\Fix T$.
\end{theorem}


In addition, when $T$ is linear, the limit can be identified and  convergence is in norm.

\begin{theorem} \label{thm:affine}
 Let $T:\mathcal H\to\mathcal H$ be linear, nonexpansive and asymptotically regular. Then for any $x_0\in\mathcal H$, in norm,
   $$\lim_{n\to\infty}T^nx_0 = P_{\Fix T}x_0.$$
\end{theorem}


\begin{corollary} \label{cor:cvgt}
 Let $T_i:\mathcal H\to\mathcal H$ be firmly nonexpansive, for each $i$, with $\bigcap_{i=1}^r\Fix T_i\neq\emptyset$ and define $T:=T_r\dots T_2T_1$. Then for any $x_0\in\mathcal H$, $T^nx_0$ converges weakly to an element of $\Fix T=\bigcap_{i=1}^N\Fix T_i$. Moreover, if $T$ is linear, then $T^nx_0$ converges, in norm, to $P_{\Fix T}x_0$.
\end{corollary}

We are now ready to introduce our first new projection algorithm, the \emph{cyclic Douglas--Rachford} iteration scheme. Let $C_1,C_2,\dots,C_N\subseteq\mathcal H$ and define $T_{[C_1\,C_2\,\dots\,C_N]}:\mathcal H\to\mathcal H$ by
  \begin{align*}
   T_{[C_1\,C_2\,\dots\,C_N]}
   &:= T_{C_N,C_1}T_{C_{N-1},C_N}\dots T_{C_2,C_3}T_{C_1,C_2} \\
   &= \left(\frac{I+R_{C_1}R_{C_N}}{2}\right) \left(\frac{I+R_{C_N}R_{C_{N-1}}}{2}\right)\dots \left(\frac{I+R_{C_3}R_{C_2}}{2}\right)\left(\frac{I+R_{C_2}R_{C_1}}{2}\right).
  \end{align*}
Given $x_0\in\mathcal H$, the \emph{cyclic Douglas--Rachford} method iterates by  repeatedly setting $${x_{n+1}=T_{[C_1\,C_2\,\dots\,C_N]}x_n}.$$


\begin{framed}
 Where there is no ambiguity, we take indices modulo $N$, and abbreviate $T_{C_i,C_j}$ by $T_{i,j}$, and $T_{[C_1\,C_2\,\dots\,C_N]}$ by $T_{[1\,2\,\dots\,N]}$. In particular, $T_{0,1}:=T_{N,1},\, T_{N,N+1}:=T_{N,1},\, C_0:=C_N$ and $C_{N+1}:=C_1$.
\end{framed}

