\noindent and induced norm $\|\cdot\|$. We use $\wto$ to denote weak convergence. \vspace{1em}

We consider the $N$-set convex feasibility problem:
\begin{framed}
 \begin{equation}
  \text{Find~}~x\in \bigcap_{i=1}^N C_i\neq\emptyset~\text{ where }C_i\subseteq\mathcal H\text{ are closed and convex}. \label{eq:cfp}
 \end{equation}
\end{framed}

Given $A,B\subseteq\mathcal H$  we define the \emph{$2$-set Douglas--Rachford} operator $T_{A,B}:\mathcal H\to\mathcal H$ by
\begin{equation}\label{tab}
 T_{A,B}:=\frac{I+R_BR_A}{2}.
\end{equation}

\begin{fact} \label{fact:nonexpansive}
 Let $A,B\subseteq\mathcal H$ be closed and convex. Then $P_A$ is firmly nonexpansive, $R_A$ is nonexpansive and $T_{A,B}$ is firmly nonexpansive.
\end{fact}

\begin{fact} \label{fact:nonexpansive}
 Let $A,B\subseteq\mathcal H$ be closed and convex. Then $P_A$ is firmly nonexpansive, $R_A$ is nonexpansive and $T_{A,B}$ is firmly nonexpansive.
\end{fact}

\begin{lemma}\label{lem:asymregular}
 Let $T_i:\mathcal H\to\mathcal H$ be firmly nonexpansive, for each $i$, and define $T:=T_r\dots T_2\,T_1$. If $\Fix T\neq\emptyset$ then $T$ is asymptotically regular.
\end{lemma}

\begin{lemma} \label{lem:fixedpoints}
 Let $T_i:\mathcal H\to\mathcal H$ be firmly nonexpansive, for each $i$, and define $T:=T_r\dots T_2\,T_1$. If $\bigcap_{i=1}^r\Fix T_i\neq\emptyset$ then $\Fix T=\bigcap_{i=1}^r\Fix T_i$.
\end{lemma}

\begin{theorem}[Opial] \label{thm:opial}
 Let $T:\mathcal H\to\mathcal H$ be nonexpansive, asymptotically regular, and $\Fix T\neq\emptyset$. Then for any $x_0\in\mathcal H$, $T^nx_0$  converges weakly to an element of $\Fix T$.
\end{theorem}

In addition, when $T$ is linear, the limit can be identified and  convergence is in norm.

\begin{theorem} \label{thm:affine}
 Let $T:\mathcal H\to\mathcal H$ be linear, nonexpansive and asymptotically regular. Then for any $x_0\in\mathcal H$, in norm,
   $$\lim_{n\to\infty}T^nx_0 = P_{\Fix T}x_0.$$
\end{theorem}

\begin{corollary} \label{cor:cvgt}
 Let $T_i:\mathcal H\to\mathcal H$ be firmly nonexpansive, for each $i$, with $\bigcap_{i=1}^r\Fix T_i\neq\emptyset$ and define $T:=T_r\dots T_2T_1$. Then for any $x_0\in\mathcal H$, $T^nx_0$ converges weakly to an element of $\Fix T=\bigcap_{i=1}^N\Fix T_i$. Moreover, if $T$ is linear, then $T^nx_0$ converges, in norm, to $P_{\Fix T}x_0$.
\end{corollary}

\begin{proof}
 Since $T$ is the composition of nonexpansive operators, $T$ is nonexpansive. By  Lemma~\ref{lem:fixedpoints}, $\Fix T\neq\emptyset$. By Lemma~\ref{lem:asymregular}, $T$ is asymptotically regular.  The result now follows by Theorem~\ref{thm:opial} and Theorem~\ref{thm:affine}. 
\end{proof}

We are now ready to introduce our first new projection algorithm, the \emph{cyclic Douglas--Rachford} iteration scheme. Let $C_1,C_2,\dots,C_N\subseteq\mathcal H$ and define $T_{[C_1\,C_2\,\dots\,C_N]}:\mathcal H\to\mathcal H$ by
  \begin{align*}
   T_{[C_1\,C_2\,\dots\,C_N]}
   &:= T_{C_N,C_1}T_{C_{N-1},C_N}\dots T_{C_2,C_3}T_{C_1,C_2} \\
   &= \left(\frac{I+R_{C_1}R_{C_N}}{2}\right) \left(\frac{I+R_{C_N}R_{C_{N-1}}}{2}\right)\dots \left(\frac{I+R_{C_3}R_{C_2}}{2}\right)\left(\frac{I+R_{C_2}R_{C_1}}{2}\right).
  \end{align*}

\begin{framed}
 Where there is no ambiguity, we take indices modulo $N$, and abbreviate $T_{C_i,C_j}$ by $T_{i,j}$, and $T_{[C_1\,C_2\,\dots\,C_N]}$ by $T_{[1\,2\,\dots\,N]}$. In particular, $T_{0,1}:=T_{N,1},\, T_{N,N+1}:=T_{N,1},\, C_0:=C_N$ and $C_{N+1}:=C_1$.
\end{framed}

\begin{lemma} \label{lem:drfp}
 Let $A,B\subseteq\mathcal H$ be closed and convex with nonempty intersection. Then 
  $$P_A\Fix T_{A,B}= A\cap B.$$
\end{lemma}

\begin{proof}
 $P_A\Fix T_{A,B}\subseteq A\cap B$ since
 \begin{equation*}
  x\in\Fix T_{A,B}\iff\frac{x+R_{B}R_{A}x}{2}=x \iff P_{A}x=P_{B}R_{A}x\in A\cap B.
 \end{equation*}
 It is straightforward to check the reverse inclusion.
\end{proof}

$P_A\Fix T_{A,B}\subseteq A\cap B$ since
\begin{equation*}
 x\in\Fix T_{A,B}\iff\frac{x+R_{B}R_{A}x}{2}=x \iff P_{A}x=P_{B}R_{A}x\in A\cap B.
\end{equation*}

\begin{theorem}[Cyclic Douglas--Rachford] \label{thm:main}
  Let $C_1,C_2,\dots,C_N\subseteq\mathcal H$ be closed and convex sets with a nonempty intersection. For any $x_0\in\mathcal H$, the sequence $T^n_{[1\,2\,\dots\,N]}x_0$ converges weakly to a point $x$ such that $P_{C_i}x = P_{C_j}x$, for all indices $i,j$. Moreover, $P_{C_j}x\in \bigcap_{i=1}^NC_i$, for each index $j$.
\end{theorem}

\begin{proof}
By Fact~\ref{fact:nonexpansive}, $T_{i,i+1}$ is firmly nonexpansive, for each $i$. Further,
$$\bigcap_{i=1}^N\Fix T_{i,i+1}\supseteq\bigcap_{i=1}^NC_i\neq\emptyset.$$
By Corollary~\ref{cor:cvgt}, $T^n_{[1\,2\,\dots\,N]}x_0$ converges weakly to a point $x\in\Fix T_{[1\,2\,\dots\,N]}=\bigcap_{i=1}^N\Fix T_{i,i+1}$. By Lemma~\ref{lem:drfp}, $P_{C_{i}}x\in C_{i+1}$, for each $i$. Now we compute
 \begin{align*}
  \frac{1}{2}\sum_{i=1}^N \|P_{C_{i}}x-P_{C_{i-1}}x\|^2
  &= \langle x,0\rangle+\frac{1}{2}\sum_{i=1}^N \left( \|P_{C_{i}}x\|^2-2\langle P_{C_{i}}x,P_{C_{i-1}}x\rangle +\|P_{C_{i-1}}x\|^2\right)\\
  &= \left\langle x, \sum_{i=1}^N (P_{C_{i-1}}x-P_{C_{i}}x)\right\rangle -\sum_{i=1}^N\langle P_{C_{i}}x,P_{C_{i-1}}x\rangle+ \sum_{i=1}^N \|P_{C_{i}}x\|^2 \\
  &=\sum_{i=1}^N \langle x-P_{C_{i}}x,P_{C_{i-1}}x-P_{C_{i}}x\rangle \stackrel{\text{Fact~\ref{fact:projections}}}{\leq} 0.
 \end{align*}
Thus, $P_{C_{i}}x=P_{C_{i-1}}x$, for each $i$; and we are done. 
\end{proof}
